window.kbPageData["views/entry/k-59b565dd08ecf729"] = {"key":"entry/k-59b565dd08ecf729","state":{"route":"entry/k-59b565dd08ecf729"},"node":{"id":"k-59b565dd08ecf729","mode":"k","title":"圆环面积","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["圆面积为π乘半径平方，圆环面积为外圆与内圆的面积差","圆环面积等于外圆面积减内圆面积"],"qs":["江苏 2025 A类 行测#57","江苏 2025 C类 行测#57"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"两个同心圆之间的圆环面积等于外圆面积减去内圆面积。若外半径为 R、内半径为 r，则面积为 π(R²－r²)。","review":{"definition":"两个同心圆之间的圆环面积等于外圆面积减去内圆面积。若外半径为 R、内半径为 r，则面积为 π(R²－r²)。","explanation":"本题 6.0 至 6.9 环所在的圆环，以 6 环圆的外缘为外边界，以 7 环圆的外缘为内边界。两圆直径分别为 20.5 毫米和 15.5 毫米，换算为半径后，面积为 π(10.25²－7.75²)＝45π 平方毫米，用作命中概率的分子。","references":[],"evidence":"即处在6环所在圆环中","disposition":"独立词条","basis":"据原题和解析编释。","title":"圆环面积","related":[],"examFocus":{"江苏 2025 A类 行测#57":"根据相邻同心圆的直径差确定目标环带的边界，用环带面积占整个靶面面积的比例判断命中概率。"}},"readings":[{"origin":"k-59b565dd08ecf729","title":"圆环面积","qs":["江苏 2025 A类 行测#57"],"definition":"两个同心圆之间的圆环面积等于外圆面积减去内圆面积。若外半径为 R、内半径为 r，则面积为 π(R²－r²)。","explanation":"本题 6.0 至 6.9 环所在的圆环，以 6 环圆的外缘为外边界，以 7 环圆的外缘为内边界。两圆直径分别为 20.5 毫米和 15.5 毫米，换算为半径后，面积为 π(10.25²－7.75²)＝45π 平方毫米，用作命中概率的分子。","evidence":"即处在6环所在圆环中","doubt":"","references":[]},{"origin":"k-f2b510bca02e22f6","title":"圆环面积","qs":["江苏 2025 C类 行测#57"],"definition":"圆环是两个同心圆之间的区域。外圆半径为 R、内圆半径为 r 时，圆环面积为 π(R²−r²)。","explanation":"本题的6.0至6.9环区域位于直径20.5毫米的6环边界和直径15.5毫米的7环边界之间。用外圆面积减去内圆面积，得到 π(10.25²−7.75²)=45π 平方毫米，作为计算命中概率的分子。","evidence":"即处在6环所在圆环中","doubt":"","references":[]}]},"questions":{"江苏 2025 A类 行测#57":{"paper":"江苏 2025 A类 行测","n":57,"mod":"数量关系","src":["98687766ac277f427cd6.pdf",12],"asrc":["4fe8e0544dd7b47699d2.pdf",18],"card":"38b4cd2d8a244978a9dc014b","links":[{"id":"k-59b565dd08ecf729","role":"解题依据","why":"目标分值区间对应同心圆之间的区域，面积由两个边界圆的面积差给出。"}]},"江苏 2025 C类 行测#57":{"paper":"江苏 2025 C类 行测","n":57,"mod":"数量关系","src":["ffc394a1c160f331ec57.pdf",12],"asrc":["d1de3b437151c05b769e.pdf",17],"card":"229c36af6c37478d829ff33a","links":[{"id":"k-59b565dd08ecf729","role":"解题依据","why":"目标区域是两个同心圆之间的圆环，面积须由内外圆面积相减得到。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-59b565dd08ecf729":[["江苏 2025 A类 行测#57","江苏 2025 C类 行测#57"]]}};
